-- Content-only, guarded, 10 tasks: applied-ai-engineering
BEGIN;
CREATE TEMP TABLE legacy_guides(payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO legacy_guides(payload) VALUES ($legacy_payload$[{"slug":"applied-ai-engineering","task_number":1,"title":"Reliable Prompt Template","old_description":"[[AZ]]\nTəkrarlana bilən prompt şablonu qur və onun qeyri-müəyyən girişlərdə necə davranacağını yoxla.\n\n[[EN]]\nBuild a reusable prompt template and test how it behaves with ambiguous inputs.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAI üçün təkrar istifadə edilən prompt hazırlayacaqsan. Prompt mesajları “ödəniş”, “hesaba giriş” və “digər” kateqoriyalarına ayırmalı, nəticəni JSON formatında qaytarmalıdır.\n\n## 2. Başlamazdan əvvəl\nPrompt və JSON anlayışları, VS Code və GitHub-dan əsas istifadə. Real şəxsi məlumat yox, uydurma mesajlar işlət.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `ai-prompt-practice` repo-su yarat və VS Code-da aç. Bu tapşırıq ilk tapşırıqdır: hər şeyi sıfırdan qur.\n2. `README.md`, `prompt.md`, `test-cases.json` və `results.md` faylları yarat.\n3. Promptda modelin rolunu, 3 kateqoriyanı, tələb olunan JSON sahələrini və anlaşılmayan mesaj üçün davranışı yaz.\n4. `test-cases.json` faylına 12 uydurma mesaj əlavə et; ən azı 3-ü qısa və qeyri-müəyyən olsun.\n5. Hər mesaj üçün gözlənilən kateqoriyanı qeyd et, promptu sına və nəticəni yaz. Modelə çıxışın yoxdursa, simulyasiya etdiyini açıq göstər.\n6. Ən azı 3 səhvi tap, promptu yaxşılaşdır və əvvəlki/yeni nəticələri müqayisə et.\n7. README-də faylları izah et; commit edib öz repo-na push et. API açarı və parolu GitHub-a yükləmə.\n\n## 4. Konkret nümunə və izah\n“Ödənişim görünmür” mesajı üçün gözlənilən cavab: `{\"category\":\"payment\",\"needs_clarification\":false}`. Qeyri-müəyyən “alınmır” mesajında aydınlaşdırma tələb olunduğunu göstər. JSON sahələrini əvvəlcədən sabitlə.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, prompt faylı, 12 test mesajı, nəticə müqayisə cədvəli və ən azı 3 səhv/düzəliş izahı.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n12 mesajın hər biri üçün gözlənilən və alınan kateqoriya yazılıb; JSON oxuna bilir; 3 səhvin əvvəlki və düzəldilmiş nəticəsi müqayisə olunur.\n\n[[EN]]\n## 1. Goal\nCreate a reusable AI prompt that classifies messages as “billing,” “account access,” or “other” and returns JSON.\n\n## 2. Before you start\nBasic prompt and JSON concepts, plus basic VS Code and GitHub use. Use fictional messages, never real personal data.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `ai-prompt-practice` and open it in VS Code. This is the first task, so start from scratch.\n2. Create `README.md`, `prompt.md`, `test-cases.json`, and `results.md`.\n3. In the prompt, define the role, three categories, required JSON fields, and behavior for unclear messages.\n4. Add 12 fictional messages to `test-cases.json`; at least three must be short or ambiguous.\n5. Record the expected category, test the prompt, and write down the result. If you cannot access a model, clearly label the test as a simulation.\n6. Find at least three errors, improve the prompt, and compare the old and new results.\n7. Explain the files in README, then commit and push to your own repository. Never upload API keys or passwords.\n\n## 4. Concrete example and explanation\nFor “My payment is missing”, expect `{\"category\":\"payment\",\"needs_clarification\":false}`. Mark an ambiguous “It does not work” as needing clarification. Fix the JSON fields before testing.\n\n## 5. What to submit\nYour own GitHub repository link, prompt file, 12 test messages, a results comparison table, and explanations of at least three errors and fixes.\n\n## 6. How to check your work\nAll 12 messages have expected and actual categories; output parses as JSON; three failures include before/after results.","new_description":"[[AZ]]\nTəkrarlana bilən prompt şablonu qur və onun qeyri-müəyyən girişlərdə necə davranacağını yoxla.\n\nPulsuz alətlər: Google AI Studio (free tier) / ChatGPT Free, Google Docs (personal), Google Sheets (personal). Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nBuild a reusable prompt template and test how it behaves with ambiguous inputs.\n\nFree tools: Google AI Studio (free tier) / ChatGPT Free, Google Docs (personal), Google Sheets (personal). See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Uydurma 'Giriş kodumu unutdum' mesajına {'category':'account','confidence':0.9} formatında cavab nümunəsi yaz.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Google AI Studio (free tier) / ChatGPT Free** — https://aistudio.google.com. Sintetik mətnlə promptu pulsuz limit daxilində sına; ödənişli API, bank kartı və şəxsi məlumat tələb edilmir.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / applied-ai-engineering / task-1` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. 'account','payment','other' etiketlərini və nümunə mesajları cədvələ yaz. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Promptda yalnız JSON cavab verilməsi və anlaşılmayan mətn üçün 'other' qaydasını müəyyən et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Eyni 10 sintetik mesajı iki dəfə sınayıb etiketlərin ardıcıllığını müqayisə et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Uydurma 'Giriş kodumu unutdum' mesajına {'category':'account','confidence':0.9} formatında cavab nümunəsi yaz. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nUydurma 'Giriş kodumu unutdum' mesajına {'category':'account','confidence':0.9} formatında cavab nümunəsi yaz.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAI üçün təkrar istifadə edilən prompt hazırlayacaqsan. Prompt mesajları “ödəniş”, “hesaba giriş” və “digər” kateqoriyalarına ayırmalı, nəticəni JSON formatında qaytarmalıdır.\n\n## 2. Başlamazdan əvvəl\nPrompt və JSON anlayışları, VS Code və GitHub-dan əsas istifadə. Real şəxsi məlumat yox, uydurma mesajlar işlət.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `ai-prompt-practice` repo-su yarat və VS Code-da aç. Bu tapşırıq ilk tapşırıqdır: hər şeyi sıfırdan qur.\n2. `README.md`, `prompt.md`, `test-cases.json` və `results.md` faylları yarat.\n3. Promptda modelin rolunu, 3 kateqoriyanı, tələb olunan JSON sahələrini və anlaşılmayan mesaj üçün davranışı yaz.\n4. `test-cases.json` faylına 12 uydurma mesaj əlavə et; ən azı 3-ü qısa və qeyri-müəyyən olsun.\n5. Hər mesaj üçün gözlənilən kateqoriyanı qeyd et, promptu sına və nəticəni yaz. Modelə çıxışın yoxdursa, simulyasiya etdiyini açıq göstər.\n6. Ən azı 3 səhvi tap, promptu yaxşılaşdır və əvvəlki/yeni nəticələri müqayisə et.\n7. README-də faylları izah et; commit edib öz repo-na push et. API açarı və parolu GitHub-a yükləmə.\n\n## 4. Konkret nümunə və izah\n“Ödənişim görünmür” mesajı üçün gözlənilən cavab: `{\"category\":\"payment\",\"needs_clarification\":false}`. Qeyri-müəyyən “alınmır” mesajında aydınlaşdırma tələb olunduğunu göstər. JSON sahələrini əvvəlcədən sabitlə.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, prompt faylı, 12 test mesajı, nəticə müqayisə cədvəli və ən azı 3 səhv/düzəliş izahı.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n12 mesajın hər biri üçün gözlənilən və alınan kateqoriya yazılıb; JSON oxuna bilir; 3 səhvin əvvəlki və düzəldilmiş nəticəsi müqayisə olunur.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Use a fictional 'I forgot my sign-in code' message with a JSON category and confidence score.\n\n## Free tools and platforms\n- **Google AI Studio (free tier) / ChatGPT Free** — https://aistudio.google.com. Test synthetic prompts manually within free quotas; paid APIs, billing and private user data are not required.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / applied-ai-engineering / task-1` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Define account, payment and other labels with fictional example messages. Show evidence in a file, local demo or measurable test.\n4. Require JSON-only output and a clear fallback for ambiguous messages. Show evidence in a file, local demo or measurable test.\n5. Repeat the same ten tests and compare label consistency. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Use a fictional 'I forgot my sign-in code' message with a JSON category and confidence score. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nUse a fictional 'I forgot my sign-in code' message with a JSON category and confidence score.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nCreate a reusable AI prompt that classifies messages as “billing,” “account access,” or “other” and returns JSON.\n\n## 2. Before you start\nBasic prompt and JSON concepts, plus basic VS Code and GitHub use. Use fictional messages, never real personal data.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `ai-prompt-practice` and open it in VS Code. This is the first task, so start from scratch.\n2. Create `README.md`, `prompt.md`, `test-cases.json`, and `results.md`.\n3. In the prompt, define the role, three categories, required JSON fields, and behavior for unclear messages.\n4. Add 12 fictional messages to `test-cases.json`; at least three must be short or ambiguous.\n5. Record the expected category, test the prompt, and write down the result. If you cannot access a model, clearly label the test as a simulation.\n6. Find at least three errors, improve the prompt, and compare the old and new results.\n7. Explain the files in README, then commit and push to your own repository. Never upload API keys or passwords.\n\n## 4. Concrete example and explanation\nFor “My payment is missing”, expect `{\"category\":\"payment\",\"needs_clarification\":false}`. Mark an ambiguous “It does not work” as needing clarification. Fix the JSON fields before testing.\n\n## 5. What to submit\nYour own GitHub repository link, prompt file, 12 test messages, a results comparison table, and explanations of at least three errors and fixes.\n\n## 6. How to check your work\nAll 12 messages have expected and actual categories; output parses as JSON; three failures include before/after results."},{"slug":"applied-ai-engineering","task_number":2,"title":"Document Q&A Prototype","old_description":"[[AZ]]\nSintetik daxili qaydalar toplusu üzrə mənbə göstərən sual-cavab prototipi qur.\n\n[[EN]]\nBuild a source-citing Q&A prototype over a synthetic set of internal policy documents.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nSənədlərdən cavab verən sadə AI prototipi quracaqsan və cavabın hansı mətn hissəsinə əsaslandığını göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki öz AI repo-n, Python əsasları və prompt/JSON anlayışları. API açarın yoxdursa, mock model cavabı ilə interfeysi qur; real şəxsi sənəd yükləmə.\n\n## 3. Addım-addım icra\n1. Öz AI layihəndə `docs` qovluğu və prototip üçün ayrıca Python faylı yarat. Python seçmirsənsə, bildiyin dildə eyni lokal axını qur və necə başladıldığını yaz.\n2. 3–5 qısa uydurma sənəd yarat; hər birində başlıq və bir neçə qayda olsun. Sənəd adını mənbə kimi saxla.\n3. Mətnləri abzaslara böl, hər abzasa ID ver. İlkin axtarışda sualdakı sözlərlə üst-üstə düşən abzasları seçmək kifayətdir.\n4. Sualı, tapılmış abzasları və mənbə ID-lərini modelə ver. API çıxışın yoxdursa, seçilmiş abzası cavab kimi göstərən simulyasiya yaz və bunu açıq qeyd et.\n5. Cavabın yanında sənəd adı və abzas ID-si görünsün. Heç bir uyğun abzas yoxdursa “Sənədlərdə cavab tapılmadı” göstər.\n6. Ən azı 8 sualı gözlənilən mənbə və cavabla cədvəldə yoxla; sənədlərdə cavabı olmayan sualları da daxil et.\n\n## 4. Konkret nümunə və izah\n3 uydurma qayda faylı yarat: iş saatları, məzuniyyət və müraciətlər. Hər mətn hissəsinə sənəd adı və hissə nömrəsi ver. “İş saatı nə vaxt başlayır?” cavabında uyğun hissəni göstər; sənədlərdə olmayan maaş sualına məlumat tapılmadığını bildir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən lokal prototip və ya mock, nümunə sənədlər, 8 suallıq test cədvəli və mənbə göstərmə davranışının screenshot-u. Uydurma cavabı fakt kimi təqdim etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n8 sualın ən azı ikisinin cavabı sənədlərdə yoxdur. Hər əsaslandırılmış cavabın göstərdiyi mənbə açıla bilir. Model simulyasiyası ilə həqiqi model nəticələri ayrıca işarələnib.\n\n[[EN]]\n## 1. Goal\nBuild a simple AI prototype that answers questions from documents and shows which text supports each answer.\n\n## 2. Before you start\nYour own AI repository from Task 1, Python basics, and prompt/JSON concepts. If you have no API key, build the interface with a mock model response; do not upload private documents.\n\n## 3. Step-by-step work\n1. Add a docs folder and a separate Python prototype file to your AI project. Another familiar language is acceptable if you implement and document the same local flow.\n2. Create 3–5 short fictional documents with titles and a few rules. Preserve filenames as source identifiers.\n3. Split text into paragraphs and assign IDs. A first version can retrieve paragraphs by matching words from the question.\n4. Pass the question, retrieved paragraphs, and source IDs to the model. Without API access, return the selected passage using a clearly labelled simulation.\n5. Display the document name and paragraph ID with each answer. Show “No answer found in the documents” when there is no relevant passage.\n6. Test at least eight questions in a table of expected sources/answers, including questions the documents cannot answer.\n\n## 4. Concrete example and explanation\nCreate three fictional policy files: working hours, leave, and applications. Label each text passage with its document and passage number. Cite the hours passage for a working-hours question; report no evidence for a salary question absent from the files.\n\n## 5. What to submit\nYour own GitHub repository link, working local prototype or mock, sample documents, an eight-question test table, and a screenshot showing source attribution. Do not present invented answers as facts.\n\n## 6. How to check your work\nAt least two of eight questions have no answer in the documents. Every supported answer has an inspectable source. Simulated and real model outputs are labelled separately.","new_description":"[[AZ]]\nSintetik daxili qaydalar toplusu üzrə mənbə göstərən sual-cavab prototipi qur.\n\nPulsuz alətlər: Python (free), Visual Studio Code, GitHub Free. Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nBuild a source-citing Q&A prototype over a synthetic set of internal policy documents.\n\nFree tools: Python (free), Visual Studio Code, GitHub Free. See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** `policy_1.md`-də 'İmtina üçün 7 gün', `policy_2.md`-də 'Dəstək emaili' yazıb sualların yanında mənbə ID-lərini göstər.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / applied-ai-engineering / task-2` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. 3 kiçik sintetik sənəd və hər birinə unikal mənbə ID-si yarat. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Sadə Python axtarışı ilə suala uyğun hissəni tap; cavabda mənbə ID-si olsun. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Sənəddə cavab olmayan sual üçün 'Bu mənbələrdə məlumat yoxdur' nəticəsini sınayıb qeyd et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: `policy_1.md`-də 'İmtina üçün 7 gün', `policy_2.md`-də 'Dəstək emaili' yazıb sualların yanında mənbə ID-lərini göstər. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\n`policy_1.md`-də 'İmtina üçün 7 gün', `policy_2.md`-də 'Dəstək emaili' yazıb sualların yanında mənbə ID-lərini göstər.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nSənədlərdən cavab verən sadə AI prototipi quracaqsan və cavabın hansı mətn hissəsinə əsaslandığını göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki öz AI repo-n, Python əsasları və prompt/JSON anlayışları. API açarın yoxdursa, mock model cavabı ilə interfeysi qur; real şəxsi sənəd yükləmə.\n\n## 3. Addım-addım icra\n1. Öz AI layihəndə `docs` qovluğu və prototip üçün ayrıca Python faylı yarat. Python seçmirsənsə, bildiyin dildə eyni lokal axını qur və necə başladıldığını yaz.\n2. 3–5 qısa uydurma sənəd yarat; hər birində başlıq və bir neçə qayda olsun. Sənəd adını mənbə kimi saxla.\n3. Mətnləri abzaslara böl, hər abzasa ID ver. İlkin axtarışda sualdakı sözlərlə üst-üstə düşən abzasları seçmək kifayətdir.\n4. Sualı, tapılmış abzasları və mənbə ID-lərini modelə ver. API çıxışın yoxdursa, seçilmiş abzası cavab kimi göstərən simulyasiya yaz və bunu açıq qeyd et.\n5. Cavabın yanında sənəd adı və abzas ID-si görünsün. Heç bir uyğun abzas yoxdursa “Sənədlərdə cavab tapılmadı” göstər.\n6. Ən azı 8 sualı gözlənilən mənbə və cavabla cədvəldə yoxla; sənədlərdə cavabı olmayan sualları da daxil et.\n\n## 4. Konkret nümunə və izah\n3 uydurma qayda faylı yarat: iş saatları, məzuniyyət və müraciətlər. Hər mətn hissəsinə sənəd adı və hissə nömrəsi ver. “İş saatı nə vaxt başlayır?” cavabında uyğun hissəni göstər; sənədlərdə olmayan maaş sualına məlumat tapılmadığını bildir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən lokal prototip və ya mock, nümunə sənədlər, 8 suallıq test cədvəli və mənbə göstərmə davranışının screenshot-u. Uydurma cavabı fakt kimi təqdim etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n8 sualın ən azı ikisinin cavabı sənədlərdə yoxdur. Hər əsaslandırılmış cavabın göstərdiyi mənbə açıla bilir. Model simulyasiyası ilə həqiqi model nəticələri ayrıca işarələnib.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Create two fictional policy Markdown documents and answer questions with source IDs.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / applied-ai-engineering / task-2` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Create three short fictional documents with unique source IDs. Show evidence in a file, local demo or measurable test.\n4. Use a simple Python keyword search to select matching passages and cite the IDs. Show evidence in a file, local demo or measurable test.\n5. Test a question whose answer is absent and return 'not found in provided sources'. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Create two fictional policy Markdown documents and answer questions with source IDs. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nCreate two fictional policy Markdown documents and answer questions with source IDs.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nBuild a simple AI prototype that answers questions from documents and shows which text supports each answer.\n\n## 2. Before you start\nYour own AI repository from Task 1, Python basics, and prompt/JSON concepts. If you have no API key, build the interface with a mock model response; do not upload private documents.\n\n## 3. Step-by-step work\n1. Add a docs folder and a separate Python prototype file to your AI project. Another familiar language is acceptable if you implement and document the same local flow.\n2. Create 3–5 short fictional documents with titles and a few rules. Preserve filenames as source identifiers.\n3. Split text into paragraphs and assign IDs. A first version can retrieve paragraphs by matching words from the question.\n4. Pass the question, retrieved paragraphs, and source IDs to the model. Without API access, return the selected passage using a clearly labelled simulation.\n5. Display the document name and paragraph ID with each answer. Show “No answer found in the documents” when there is no relevant passage.\n6. Test at least eight questions in a table of expected sources/answers, including questions the documents cannot answer.\n\n## 4. Concrete example and explanation\nCreate three fictional policy files: working hours, leave, and applications. Label each text passage with its document and passage number. Cite the hours passage for a working-hours question; report no evidence for a salary question absent from the files.\n\n## 5. What to submit\nYour own GitHub repository link, working local prototype or mock, sample documents, an eight-question test table, and a screenshot showing source attribution. Do not present invented answers as facts.\n\n## 6. How to check your work\nAt least two of eight questions have no answer in the documents. Every supported answer has an inspectable source. Simulated and real model outputs are labelled separately."},{"slug":"applied-ai-engineering","task_number":3,"title":"AI Evaluation Report","old_description":"[[AZ]]\nKiçik etalon dəstində AI cavab keyfiyyətini ölç və qərarını rəqəmlə əsaslandır.\n\n[[EN]]\nMeasure AI answer quality on a small benchmark and justify decisions with evidence.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAI cavablarının nə dərəcədə düzgün və faydalı olduğunu sistemli testlərlə ölçəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz AI prototipin, Tapşırıq 2-dəki sənədlər və gözlənilən cavablar. Real istifadəçi məlumatı yox, sintetik suallar istifadə et.\n\n## 3. Addım-addım icra\n1. Öz AI repo-nu davam etdir.\n2. Müxtəlif tipli ən azı 20 sual hazırla: cavabı olan, cavabı olmayan, qeyri-müəyyən və əlaqəsiz.\n3. Hər sual üçün gözlənilən cavabın əsas fikrini və mənbəni yaz.\n4. Model cavabını düzgünlük, mənbəyə uyğunluq və faydalılıq üzrə qiymətləndir.\n5. Səhvləri kateqoriyalara böl və ən çox təkrarlanan 3 problemi seç.\n6. Bir prompt/retrieval düzəlişi et və əvvəl/sonra nəticələrini müqayisə et.\n\n## 4. Konkret nümunə və izah\nHər cavabı üç meyar üzrə 0 və ya 1 balla qiymətləndir: düzgün fikir, uyğun mənbə, istifadəçiyə aydınlıq. Məsələn, cavab düzgündür, amma mənbə yanlışdırsa 1+0+1=2/3 baldır. Qiymətləndirmə qaydasını nəticələrə baxmazdan əvvəl yaz.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 20+ testlik qiymətləndirmə cədvəli, scoring qaydası, 3 əsas səhv və bir yaxşılaşdırmanın müqayisəsi. Ölçülməyən nəticəni iddia etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nEyni 20 sual və eyni qiymətləndirmə qaydası əvvəl/sonra istifadə olunub. Hər balın səbəbi və uğursuz cavabın nümunəsi göstərilib.\n\n[[EN]]\n## 1. Goal\nMeasure AI answer quality systematically with repeatable tests.\n\n## 2. Before you start\nYour AI prototype, documents from Task 2, and expected answers. Use synthetic questions, not real user data.\n\n## 3. Step-by-step work\n1. Continue your own AI repository.\n2. Prepare at least 20 questions: answerable, unanswerable, ambiguous, and unrelated.\n3. Record the expected key point and source for each question.\n4. Score model answers for correctness, source alignment, and usefulness.\n5. Group failures and identify the three most frequent problems.\n6. Make one prompt/retrieval improvement and compare before/after results.\n\n## 4. Concrete example and explanation\nScore each answer 0 or 1 for correctness, source support, and clarity. A correct, clear answer with a wrong source scores 1+0+1=2/3. Define the rubric before inspecting outputs.\n\n## 5. What to submit\nYour own GitHub repository link, an evaluation table with 20+ tests, scoring rules, three key failure types, and a before/after comparison. Do not claim improvements you did not measure.\n\n## 6. How to check your work\nUse the same 20 questions and rubric before and after. Explain each score and show failed answers.","new_description":"[[AZ]]\nKiçik etalon dəstində AI cavab keyfiyyətini ölç və qərarını rəqəmlə əsaslandır.\n\nPulsuz alətlər: Google Sheets (personal), Python (free), Google AI Studio (free tier) / ChatGPT Free. Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nMeasure AI answer quality on a small benchmark and justify decisions with evidence.\n\nFree tools: Google Sheets (personal), Python (free), Google AI Studio (free tier) / ChatGPT Free. See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** 10 uydurma sual üçün gözlənilən cavab, AI cavabı, düzgünlük (0/1) və mənbə uyğunluğunu cədvəldə qiymətləndir.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Google AI Studio (free tier) / ChatGPT Free** — https://aistudio.google.com. Sintetik mətnlə promptu pulsuz limit daxilində sına; ödənişli API, bank kartı və şəxsi məlumat tələb edilmir.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / applied-ai-engineering / task-3` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Etalon cavablar olan 10 sətirlik test cədvəli qur. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Doğruluq və mənbə düzgünlüyü üzrə ayrıca sütun doldur; qiymətləndirmə qaydasını yaz. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Düzgünlük faizini hesabla, ən çox təkrarlanan iki səhv səbəbini göstər. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: 10 uydurma sual üçün gözlənilən cavab, AI cavabı, düzgünlük (0/1) və mənbə uyğunluğunu cədvəldə qiymətləndir. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\n10 uydurma sual üçün gözlənilən cavab, AI cavabı, düzgünlük (0/1) və mənbə uyğunluğunu cədvəldə qiymətləndir.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAI cavablarının nə dərəcədə düzgün və faydalı olduğunu sistemli testlərlə ölçəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz AI prototipin, Tapşırıq 2-dəki sənədlər və gözlənilən cavablar. Real istifadəçi məlumatı yox, sintetik suallar istifadə et.\n\n## 3. Addım-addım icra\n1. Öz AI repo-nu davam etdir.\n2. Müxtəlif tipli ən azı 20 sual hazırla: cavabı olan, cavabı olmayan, qeyri-müəyyən və əlaqəsiz.\n3. Hər sual üçün gözlənilən cavabın əsas fikrini və mənbəni yaz.\n4. Model cavabını düzgünlük, mənbəyə uyğunluq və faydalılıq üzrə qiymətləndir.\n5. Səhvləri kateqoriyalara böl və ən çox təkrarlanan 3 problemi seç.\n6. Bir prompt/retrieval düzəlişi et və əvvəl/sonra nəticələrini müqayisə et.\n\n## 4. Konkret nümunə və izah\nHər cavabı üç meyar üzrə 0 və ya 1 balla qiymətləndir: düzgün fikir, uyğun mənbə, istifadəçiyə aydınlıq. Məsələn, cavab düzgündür, amma mənbə yanlışdırsa 1+0+1=2/3 baldır. Qiymətləndirmə qaydasını nəticələrə baxmazdan əvvəl yaz.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 20+ testlik qiymətləndirmə cədvəli, scoring qaydası, 3 əsas səhv və bir yaxşılaşdırmanın müqayisəsi. Ölçülməyən nəticəni iddia etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nEyni 20 sual və eyni qiymətləndirmə qaydası əvvəl/sonra istifadə olunub. Hər balın səbəbi və uğursuz cavabın nümunəsi göstərilib.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Score ten fictional questions for correctness and source support.\n\n## Free tools and platforms\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Google AI Studio (free tier) / ChatGPT Free** — https://aistudio.google.com. Test synthetic prompts manually within free quotas; paid APIs, billing and private user data are not required.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / applied-ai-engineering / task-3` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Build ten benchmark rows with expected answers. Show evidence in a file, local demo or measurable test.\n4. Score correctness and source accuracy separately using a documented rubric. Show evidence in a file, local demo or measurable test.\n5. Calculate the accuracy percentage and identify two frequent error types. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Score ten fictional questions for correctness and source support. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nScore ten fictional questions for correctness and source support.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nMeasure AI answer quality systematically with repeatable tests.\n\n## 2. Before you start\nYour AI prototype, documents from Task 2, and expected answers. Use synthetic questions, not real user data.\n\n## 3. Step-by-step work\n1. Continue your own AI repository.\n2. Prepare at least 20 questions: answerable, unanswerable, ambiguous, and unrelated.\n3. Record the expected key point and source for each question.\n4. Score model answers for correctness, source alignment, and usefulness.\n5. Group failures and identify the three most frequent problems.\n6. Make one prompt/retrieval improvement and compare before/after results.\n\n## 4. Concrete example and explanation\nScore each answer 0 or 1 for correctness, source support, and clarity. A correct, clear answer with a wrong source scores 1+0+1=2/3. Define the rubric before inspecting outputs.\n\n## 5. What to submit\nYour own GitHub repository link, an evaluation table with 20+ tests, scoring rules, three key failure types, and a before/after comparison. Do not claim improvements you did not measure.\n\n## 6. How to check your work\nUse the same 20 questions and rubric before and after. Explain each score and show failed answers."},{"slug":"applied-ai-engineering","task_number":4,"title":"Integrated AI Product Feature","old_description":"[[AZ]]\nKiçik, istifadəçiyə yönəlmiş AI funksiyasını tələbdən ölçülən nəticəyə qədər tamamla.\n\n[[EN]]\nComplete a small user-facing AI feature from requirements through measurable evaluation.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nİstifadəçi sualından cavab hazırlayan AI funksiyasını təhlükəsizlik, xəta idarəetməsi və qiymətləndirmə ilə tamamlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki AI layihən, prompt, retrieval, API error və test anlayışları. Ödənişli model məcburi deyil; mock/local alternativ qəbul edilir.\n\n## 3. Addım-addım icra\n1. Tapşırıq 1–3-dəki öz repo-nu davam etdir.\n2. Sual → relevant context → answer axınını birləşdir.\n3. Source attribution, empty result, timeout və provider error hallarını idarə et.\n4. Input ölçüsünə limit qoy və istifadəçi mətnini instruction kimi kor-koranə icra etmə.\n5. Əvvəlki qiymətləndirmə dataset-indən testləri təkrar işə sal.\n6. README-də setup, model/mock seçimi, məhdudiyyətlər və məlum riskləri yaz.\n\n## 4. Konkret nümunə və izah\nİstifadəçi sual verir → sistem sənədlərdən uyğun hissəni tapır → cavab və mənbə göstərilir. Şəbəkə cavab vermədikdə istifadəçiyə yenidən cəhd təklif edilir. Bu mərhələ işlək prototipdir; yekun təhvil 10-cu tapşırıqda olacaq.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işlək AI feature, test nəticələri, error-state screenshot-ları və setup guide. Cavab mənbə ilə əsaslandırılmalı, xətalar təhlükəsiz idarə olunmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nMənbəli cavab, məlumat tapılmaması, vaxt limiti və model xidmətinin xətası ayrı-ayrılıqda yoxlanılıb. Əvvəlki 20 suallıq sınaq yenidən icra olunub.\n\n[[EN]]\n## 1. Goal\nComplete an AI answering feature with safety checks, error handling, and evaluation.\n\n## 2. Before you start\nYour earlier AI project, prompting, retrieval, API errors, and testing. A paid model is not required; a mock/local alternative is acceptable.\n\n## 3. Step-by-step work\n1. Continue your own repository from Tasks 1–3.\n2. Connect the question → relevant context → answer flow.\n3. Handle source attribution, empty results, timeouts, and provider errors.\n4. Limit input size and do not blindly treat user-provided text as instructions.\n5. Rerun tests from your evaluation dataset.\n6. Document setup, model/mock choice, limitations, and known risks in the README.\n\n## 4. Concrete example and explanation\nQuestion → relevant document passage → answer with a source. A network timeout offers a retry. This is an integrated prototype; the final handoff comes in Task 10.\n\n## 5. What to submit\nYour own GitHub repository link, working AI feature, test results, error-state screenshots, and setup guide. Answers must be grounded in sources and failures handled safely.\n\n## 6. How to check your work\nTest sourced answers, no evidence, timeout, and provider failure separately. Rerun the earlier 20-question evaluation.","new_description":"[[AZ]]\nKiçik, istifadəçiyə yönəlmiş AI funksiyasını tələbdən ölçülən nəticəyə qədər tamamla.\n\nPulsuz alətlər: Python (free), FastAPI (open source), Visual Studio Code, GitHub Free. Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nComplete a small user-facing AI feature from requirements through measurable evaluation.\n\nFree tools: Python (free), FastAPI (open source), Visual Studio Code, GitHub Free. See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Lokal FastAPI `/answer` endpoint-i JSON sual qəbul edib mənbəli cavab və ya aydın xəta qaytarsın; AI modeli üçün ödənişli API lazım deyil.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / applied-ai-engineering / task-4` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Giriş/çıxış JSON modelini Pydantic ilə müəyyən et; boş və çox uzun sualları rədd et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Əvvəlki Q&A modulu ilə lokal endpoint qur; model istifadə edə bilməsən qayda əsaslı demo əlavə et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Uğurlu, mənbəsiz və yanlış giriş üçün testlər yaz, README-də işlətmə addımlarını göstər. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Lokal FastAPI `/answer` endpoint-i JSON sual qəbul edib mənbəli cavab və ya aydın xəta qaytarsın; AI modeli üçün ödənişli API lazım deyil. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nLokal FastAPI `/answer` endpoint-i JSON sual qəbul edib mənbəli cavab və ya aydın xəta qaytarsın; AI modeli üçün ödənişli API lazım deyil.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nİstifadəçi sualından cavab hazırlayan AI funksiyasını təhlükəsizlik, xəta idarəetməsi və qiymətləndirmə ilə tamamlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki AI layihən, prompt, retrieval, API error və test anlayışları. Ödənişli model məcburi deyil; mock/local alternativ qəbul edilir.\n\n## 3. Addım-addım icra\n1. Tapşırıq 1–3-dəki öz repo-nu davam etdir.\n2. Sual → relevant context → answer axınını birləşdir.\n3. Source attribution, empty result, timeout və provider error hallarını idarə et.\n4. Input ölçüsünə limit qoy və istifadəçi mətnini instruction kimi kor-koranə icra etmə.\n5. Əvvəlki qiymətləndirmə dataset-indən testləri təkrar işə sal.\n6. README-də setup, model/mock seçimi, məhdudiyyətlər və məlum riskləri yaz.\n\n## 4. Konkret nümunə və izah\nİstifadəçi sual verir → sistem sənədlərdən uyğun hissəni tapır → cavab və mənbə göstərilir. Şəbəkə cavab vermədikdə istifadəçiyə yenidən cəhd təklif edilir. Bu mərhələ işlək prototipdir; yekun təhvil 10-cu tapşırıqda olacaq.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işlək AI feature, test nəticələri, error-state screenshot-ları və setup guide. Cavab mənbə ilə əsaslandırılmalı, xətalar təhlükəsiz idarə olunmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nMənbəli cavab, məlumat tapılmaması, vaxt limiti və model xidmətinin xətası ayrı-ayrılıqda yoxlanılıb. Əvvəlki 20 suallıq sınaq yenidən icra olunub.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Build a localhost FastAPI /answer prototype returning source-grounded responses or explicit errors.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / applied-ai-engineering / task-4` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Define Pydantic input/output schemas and reject empty or oversized questions. Show evidence in a file, local demo or measurable test.\n4. Connect your earlier Q&A logic or a rule-based local stub; no paid API is necessary. Show evidence in a file, local demo or measurable test.\n5. Test success, missing evidence and invalid input and document local setup. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Build a localhost FastAPI /answer prototype returning source-grounded responses or explicit errors. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nBuild a localhost FastAPI /answer prototype returning source-grounded responses or explicit errors.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nComplete an AI answering feature with safety checks, error handling, and evaluation.\n\n## 2. Before you start\nYour earlier AI project, prompting, retrieval, API errors, and testing. A paid model is not required; a mock/local alternative is acceptable.\n\n## 3. Step-by-step work\n1. Continue your own repository from Tasks 1–3.\n2. Connect the question → relevant context → answer flow.\n3. Handle source attribution, empty results, timeouts, and provider errors.\n4. Limit input size and do not blindly treat user-provided text as instructions.\n5. Rerun tests from your evaluation dataset.\n6. Document setup, model/mock choice, limitations, and known risks in the README.\n\n## 4. Concrete example and explanation\nQuestion → relevant document passage → answer with a source. A network timeout offers a retry. This is an integrated prototype; the final handoff comes in Task 10.\n\n## 5. What to submit\nYour own GitHub repository link, working AI feature, test results, error-state screenshots, and setup guide. Answers must be grounded in sources and failures handled safely.\n\n## 6. How to check your work\nTest sourced answers, no evidence, timeout, and provider failure separately. Rerun the earlier 20-question evaluation."},{"slug":"applied-ai-engineering","task_number":5,"title":"Prompt Failure Cases","old_description":"[[AZ]]\nPrompt-un hansı hallarda sıradan çıxdığını ölç və düzəlişləri riskə görə prioritetləşdir.\n\n[[EN]]\nMeasure where a prompt fails and prioritize fixes by risk.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAI prompt-un hansı hallarda səhv cavab verdiyini tapıb daha etibarlı davranış quracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz AI prototipin və əvvəlki test nəticələrin. Test üçün sintetik və zərərsiz mətnlər seç.\n\n## 3. Addım-addım icra\n1. Öz AI repo-nu davam etdir.\n2. Ən azı 10 failure case yaz: qeyri-müəyyən sual, çatışmayan kontekst, ziddiyyətli mətn, əlaqəsiz sual və prompt injection cəhdi.\n3. Hər hal üçün gözlənilən təhlükəsiz davranışı əvvəlcədən müəyyən et.\n4. Testləri işə sal və cavabları expected behavior ilə müqayisə et.\n5. Prompt və ya retrieval qaydasını dəyişərək ən azı 3 failure case-i düzəlt.\n6. Əvvəl/sonra nəticələri və qalan məhdudiyyətləri sənədləşdir.\n\n## 4. Konkret nümunə və izah\nUğursuz sınaq cədvəlində giriş, gözlənilən davranış, alınan cavab və səbəb olsun. “Əvvəlki qaydaları unut” kimi sənəd mətni sistem əmri sayılmamalıdır. Bu sınağı yalnız öz prototipində apar.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 10+ failure case, nəticə cədvəli, ən azı 3 düzəliş və regression testləri. Uğursuz sınaqları gizlətmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n10 hal qeydə alınıb; ən azı 3 düzəliş həmin halı həll edir və əvvəl işləyən cavabların pozulmadığı yenidən yoxlanılıb.\n\n[[EN]]\n## 1. Goal\nFind when your AI prompt fails and improve its reliability.\n\n## 2. Before you start\nYour AI prototype and previous test results. Use harmless synthetic text for testing.\n\n## 3. Step-by-step work\n1. Continue your own AI repository.\n2. Write at least ten failure cases: ambiguous questions, missing context, conflicting text, unrelated questions, and prompt-injection attempts.\n3. Define the expected safe behavior for each case before testing.\n4. Run tests and compare responses with expected behavior.\n5. Improve at least three failure cases by changing the prompt or retrieval rules.\n6. Document before/after results and remaining limitations.\n\n## 4. Concrete example and explanation\nUse columns for input, expected behavior, actual answer, and cause. Document text such as “Ignore previous rules” must not become a system instruction. Test only your own prototype.\n\n## 5. What to submit\nYour own GitHub repository link, ten or more failure cases, a results table, at least three fixes, and regression tests. Do not hide failed experiments.\n\n## 6. How to check your work\nRecord ten cases; fix at least three and rerun previously passing cases to check for regressions.","new_description":"[[AZ]]\nPrompt-un hansı hallarda sıradan çıxdığını ölç və düzəlişləri riskə görə prioritetləşdir.\n\nPulsuz alətlər: Google AI Studio (free tier) / ChatGPT Free, Google Sheets (personal). Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nMeasure where a prompt fails and prioritize fixes by risk.\n\nFree tools: Google AI Studio (free tier) / ChatGPT Free, Google Sheets (personal). See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Prompt 'Ödənişim necədir?' və 'Telefonla giriş etmir' kimi qarışıq sintetik mesajlarda səhv etiket versin; səbəbləri ayır.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Google AI Studio (free tier) / ChatGPT Free** — https://aistudio.google.com. Sintetik mətnlə promptu pulsuz limit daxilində sına; ödənişli API, bank kartı və şəxsi məlumat tələb edilmir.\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / applied-ai-engineering / task-5` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. 10 edge case qur: boş mətn, typo, iki mövzu, şəbəkə xətası və s. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Hər testdə gözlənilən etiketlə faktiki etiket arasındakı fərqi yaz. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Promptun ikinci versiyasını qur, həmin 10 nümunədə yaxşılaşmanı ölç. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Prompt 'Ödənişim necədir?' və 'Telefonla giriş etmir' kimi qarışıq sintetik mesajlarda səhv etiket versin; səbəbləri ayır. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nPrompt 'Ödənişim necədir?' və 'Telefonla giriş etmir' kimi qarışıq sintetik mesajlarda səhv etiket versin; səbəbləri ayır.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAI prompt-un hansı hallarda səhv cavab verdiyini tapıb daha etibarlı davranış quracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz AI prototipin və əvvəlki test nəticələrin. Test üçün sintetik və zərərsiz mətnlər seç.\n\n## 3. Addım-addım icra\n1. Öz AI repo-nu davam etdir.\n2. Ən azı 10 failure case yaz: qeyri-müəyyən sual, çatışmayan kontekst, ziddiyyətli mətn, əlaqəsiz sual və prompt injection cəhdi.\n3. Hər hal üçün gözlənilən təhlükəsiz davranışı əvvəlcədən müəyyən et.\n4. Testləri işə sal və cavabları expected behavior ilə müqayisə et.\n5. Prompt və ya retrieval qaydasını dəyişərək ən azı 3 failure case-i düzəlt.\n6. Əvvəl/sonra nəticələri və qalan məhdudiyyətləri sənədləşdir.\n\n## 4. Konkret nümunə və izah\nUğursuz sınaq cədvəlində giriş, gözlənilən davranış, alınan cavab və səbəb olsun. “Əvvəlki qaydaları unut” kimi sənəd mətni sistem əmri sayılmamalıdır. Bu sınağı yalnız öz prototipində apar.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 10+ failure case, nəticə cədvəli, ən azı 3 düzəliş və regression testləri. Uğursuz sınaqları gizlətmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n10 hal qeydə alınıb; ən azı 3 düzəliş həmin halı həll edir və əvvəl işləyən cavabların pozulmadığı yenidən yoxlanılıb.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Use ambiguous fictional payment/login messages to analyze incorrect prompt classification.\n\n## Free tools and platforms\n- **Google AI Studio (free tier) / ChatGPT Free** — https://aistudio.google.com. Test synthetic prompts manually within free quotas; paid APIs, billing and private user data are not required.\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / applied-ai-engineering / task-5` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Write ten edge cases such as empty text, typos and mixed intents. Show evidence in a file, local demo or measurable test.\n4. Compare expected versus actual labels and categorize each failure. Show evidence in a file, local demo or measurable test.\n5. Revise the prompt once and measure improvements on the same ten cases. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Use ambiguous fictional payment/login messages to analyze incorrect prompt classification. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nUse ambiguous fictional payment/login messages to analyze incorrect prompt classification.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nFind when your AI prompt fails and improve its reliability.\n\n## 2. Before you start\nYour AI prototype and previous test results. Use harmless synthetic text for testing.\n\n## 3. Step-by-step work\n1. Continue your own AI repository.\n2. Write at least ten failure cases: ambiguous questions, missing context, conflicting text, unrelated questions, and prompt-injection attempts.\n3. Define the expected safe behavior for each case before testing.\n4. Run tests and compare responses with expected behavior.\n5. Improve at least three failure cases by changing the prompt or retrieval rules.\n6. Document before/after results and remaining limitations.\n\n## 4. Concrete example and explanation\nUse columns for input, expected behavior, actual answer, and cause. Document text such as “Ignore previous rules” must not become a system instruction. Test only your own prototype.\n\n## 5. What to submit\nYour own GitHub repository link, ten or more failure cases, a results table, at least three fixes, and regression tests. Do not hide failed experiments.\n\n## 6. How to check your work\nRecord ten cases; fix at least three and rerun previously passing cases to check for regressions."},{"slug":"applied-ai-engineering","task_number":6,"title":"Tool Calling Prototype","old_description":"[[AZ]]\nAlət çağırışını sxemlə məhdudlaşdır, girişləri yoxla və alət xətalarını idarə et.\n\n[[EN]]\nConstrain a tool call with a schema, validate inputs, and handle tool failures.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAI prototipinə məhdud və yoxlanıla bilən tool/function calling əlavə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz AI repo-n, JSON schema, function input/output və API mock anlayışı. Real hesab və ödəniş əməliyyatı etmə.\n\n## 3. Addım-addım icra\n1. Öz AI layihəni davam etdir.\n2. İki təhlükəsiz funksiya müəyyən et, məsələn, task axtarışı və task detalını oxuma.\n3. Hər funksiya üçün input schema və icazə verilən parametrləri yaz.\n4. Modelin təklif etdiyi arqumentləri schema ilə yoxla; naməlum funksiyanı icra etmə.\n5. Funksiya nəticəsini modelə qaytar və son cavabda mənbəni göstər.\n6. Valid/invalid argument və tool error üçün test yaz.\n\n## 4. Konkret nümunə və izah\n`search_tasks(query)` siyahı qaytarsın, `get_task(id)` bir tapşırığı oxusun. Model yalnız bu iki adı seçə bilər. `id` boşdursa və ya funksiya adı siyahıda yoxdursa, kod çağırışı rədd etməlidir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, iki tool üçün schema/implementasiya, mock nəticələr və testlər. Tool yalnız açıq şəkildə icazə verilən əməliyyatları yerinə yetirməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər alət üçün düzgün giriş, yanlış giriş və alət xətası yoxlanılıb. Modelin özünün yazdığı ixtiyari kod icra olunmur.\n\n[[EN]]\n## 1. Goal\nAdd limited, verifiable tool/function calling to your AI prototype.\n\n## 2. Before you start\nYour own AI repository, JSON schemas, function inputs/outputs, and API mocks. Do not perform real account or payment actions.\n\n## 3. Step-by-step work\n1. Continue your own AI project.\n2. Define two safe functions, such as searching tasks and reading task details.\n3. Specify an input schema and allowed parameters for each function.\n4. Validate model-proposed arguments against the schema; never execute unknown functions.\n5. Return tool results to the model and show sources in the final answer.\n6. Test valid/invalid arguments and tool errors.\n\n## 4. Concrete example and explanation\n`search_tasks(query)` returns a list; `get_task(id)` reads one task. Only those two names are allowed. Reject empty IDs and unknown function names before executing code.\n\n## 5. What to submit\nYour own GitHub repository link, schemas/implementation for two tools, mock results, and tests. Tools must perform only explicitly allowed actions.\n\n## 6. How to check your work\nTest valid inputs, invalid inputs, and tool failures for both tools. Never execute arbitrary code emitted by the model.","new_description":"[[AZ]]\nAlət çağırışını sxemlə məhdudlaşdır, girişləri yoxla və alət xətalarını idarə et.\n\nPulsuz alətlər: Python (free), Visual Studio Code, GitHub Free. Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nConstrain a tool call with a schema, validate inputs, and handle tool failures.\n\nFree tools: Python (free), Visual Studio Code, GitHub Free. See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Yalnız `get_status('demo-123')` adlı lokal saxta funksiyaya icazə ver; naməlum funksiyanı rədd et.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / applied-ai-engineering / task-6` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Funksiya üçün JSON input schema və icazəli funksiya siyahısı hazırla. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Yanlış tip, naməlum ad və boş parametri yoxlayan validator yaz. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Uğur, validator xətası və funksiya xətası üzrə mock testləri topla; real servisə yazma. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Yalnız `get_status('demo-123')` adlı lokal saxta funksiyaya icazə ver; naməlum funksiyanı rədd et. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nYalnız `get_status('demo-123')` adlı lokal saxta funksiyaya icazə ver; naməlum funksiyanı rədd et.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAI prototipinə məhdud və yoxlanıla bilən tool/function calling əlavə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz AI repo-n, JSON schema, function input/output və API mock anlayışı. Real hesab və ödəniş əməliyyatı etmə.\n\n## 3. Addım-addım icra\n1. Öz AI layihəni davam etdir.\n2. İki təhlükəsiz funksiya müəyyən et, məsələn, task axtarışı və task detalını oxuma.\n3. Hər funksiya üçün input schema və icazə verilən parametrləri yaz.\n4. Modelin təklif etdiyi arqumentləri schema ilə yoxla; naməlum funksiyanı icra etmə.\n5. Funksiya nəticəsini modelə qaytar və son cavabda mənbəni göstər.\n6. Valid/invalid argument və tool error üçün test yaz.\n\n## 4. Konkret nümunə və izah\n`search_tasks(query)` siyahı qaytarsın, `get_task(id)` bir tapşırığı oxusun. Model yalnız bu iki adı seçə bilər. `id` boşdursa və ya funksiya adı siyahıda yoxdursa, kod çağırışı rədd etməlidir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, iki tool üçün schema/implementasiya, mock nəticələr və testlər. Tool yalnız açıq şəkildə icazə verilən əməliyyatları yerinə yetirməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər alət üçün düzgün giriş, yanlış giriş və alət xətası yoxlanılıb. Modelin özünün yazdığı ixtiyari kod icra olunmur.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Allow a local mock get_status('demo-123') function and reject unknown tool names.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / applied-ai-engineering / task-6` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Define a JSON input schema and explicit function allowlist. Show evidence in a file, local demo or measurable test.\n4. Validate types, unknown function names and missing parameters. Show evidence in a file, local demo or measurable test.\n5. Test success, validation failure and simulated tool failure without calling external systems. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Allow a local mock get_status('demo-123') function and reject unknown tool names. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nAllow a local mock get_status('demo-123') function and reject unknown tool names.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nAdd limited, verifiable tool/function calling to your AI prototype.\n\n## 2. Before you start\nYour own AI repository, JSON schemas, function inputs/outputs, and API mocks. Do not perform real account or payment actions.\n\n## 3. Step-by-step work\n1. Continue your own AI project.\n2. Define two safe functions, such as searching tasks and reading task details.\n3. Specify an input schema and allowed parameters for each function.\n4. Validate model-proposed arguments against the schema; never execute unknown functions.\n5. Return tool results to the model and show sources in the final answer.\n6. Test valid/invalid arguments and tool errors.\n\n## 4. Concrete example and explanation\n`search_tasks(query)` returns a list; `get_task(id)` reads one task. Only those two names are allowed. Reject empty IDs and unknown function names before executing code.\n\n## 5. What to submit\nYour own GitHub repository link, schemas/implementation for two tools, mock results, and tests. Tools must perform only explicitly allowed actions.\n\n## 6. How to check your work\nTest valid inputs, invalid inputs, and tool failures for both tools. Never execute arbitrary code emitted by the model."},{"slug":"applied-ai-engineering","task_number":7,"title":"RAG Quality Tuning","old_description":"[[AZ]]\nAxtarış keyfiyyətini ölçərək RAG prototipində uyğun mənbələrin tapılmasını yaxşılaşdır.\n\n[[EN]]\nImprove source retrieval in a RAG prototype by measuring search quality.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nSənədlərdən cavab tapan sistemdə retrieval keyfiyyətini yaxşılaşdıracaq və dəyişiklikləri ölçəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz document Q&A prototipin, test sualları və mənbə hissələri. Embedding/API xidmətinə çıxış yoxdursa, keyword search ilə müqayisə et.\n\n## 3. Addım-addım icra\n1. Öz AI repo-nu davam etdir.\n2. Ən azı 20 sual üçün gözlənilən source chunk-ı qeyd et.\n3. Cari retrieval nəticələrində düzgün hissənin top-k siyahısında olub-olmadığını ölç.\n4. Chunk ölçüsü və top-k dəyərini bir-bir dəyişərək sına.\n5. Düzgün source retrieval faizi və cavab keyfiyyətini əvvəl/sonra müqayisə et.\n6. Dəyişikliklərin trade-off və məhdudiyyətlərini yaz.\n\n## 4. Konkret nümunə və izah\nMətn hissəsi (chunk) sənədin kiçik parçasıdır; top-k axtarışdan götürülən hissələrin sayıdır. Əvvəl 300 söz/k=3, sonra 150 söz/k=3, sonda 150 söz/k=5 sına. 20 sualdan 15-də düzgün hissə tapılıbsa göstərici 15/20=75%-dir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, test dataset-i, retrieval ölçüləri, parametrlər üzrə müqayisə və nəticə hesabatı. Ölçüləri təkrar istehsal etmək mümkün olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər sınaqda yalnız bir parametr dəyişib; eyni sual dəsti istifadə olunub. Düzgün hissənin necə müəyyən olunduğu və əldə edilən faiz açıqdır.\n\n[[EN]]\n## 1. Goal\nImprove document retrieval quality and measure the effect of each change.\n\n## 2. Before you start\nYour document Q&A prototype, test questions, and source chunks. If embeddings/API access is unavailable, compare keyword-search alternatives.\n\n## 3. Step-by-step work\n1. Continue your own AI repository.\n2. Record the expected source chunk for at least 20 questions.\n3. Measure whether the correct chunk appears in the current top-k results.\n4. Experiment with chunk size and top-k one variable at a time.\n5. Compare source-retrieval rate and answer quality before/after.\n6. Document trade-offs and limitations.\n\n## 4. Concrete example and explanation\nA chunk is a short document passage; top-k is the number of retrieved passages. Compare 300 words/k=3, then 150 words/k=3, then 150 words/k=5. Finding the labelled passage for 15 of 20 questions gives 75%.\n\n## 5. What to submit\nYour own GitHub repository link, test dataset, retrieval metrics, parameter comparison, and report. Measurements must be reproducible.\n\n## 6. How to check your work\nChange one parameter per comparison and keep the same questions. State how relevant passages are labelled and how the percentage is calculated.","new_description":"[[AZ]]\nAxtarış keyfiyyətini ölçərək RAG prototipində uyğun mənbələrin tapılmasını yaxşılaşdır.\n\nPulsuz alətlər: Python (free), Google Sheets (personal). Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nImprove source retrieval in a RAG prototype by measuring search quality.\n\nFree tools: Python (free), Google Sheets (personal). See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** 'Sertifikat necə alınır?' sualına 3 sintetik FAQ hissəsi arasından ən uyğun 2-ni tap, `precision@2` hesabla.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / applied-ai-engineering / task-7` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Sənədləri kiçik paraqraflara böl; hər hissəyə source ID yaz. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. İki chunk ölçüsü sınayıb eyni 8 sualda ilk 2 nəticəni qeyd et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Uyğun mənbə tapılmayanda cavab uydurma, 'məlumat yoxdur' qaydasını test et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: 'Sertifikat necə alınır?' sualına 3 sintetik FAQ hissəsi arasından ən uyğun 2-ni tap, `precision@2` hesabla. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\n'Sertifikat necə alınır?' sualına 3 sintetik FAQ hissəsi arasından ən uyğun 2-ni tap, `precision@2` hesabla.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nSənədlərdən cavab tapan sistemdə retrieval keyfiyyətini yaxşılaşdıracaq və dəyişiklikləri ölçəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz document Q&A prototipin, test sualları və mənbə hissələri. Embedding/API xidmətinə çıxış yoxdursa, keyword search ilə müqayisə et.\n\n## 3. Addım-addım icra\n1. Öz AI repo-nu davam etdir.\n2. Ən azı 20 sual üçün gözlənilən source chunk-ı qeyd et.\n3. Cari retrieval nəticələrində düzgün hissənin top-k siyahısında olub-olmadığını ölç.\n4. Chunk ölçüsü və top-k dəyərini bir-bir dəyişərək sına.\n5. Düzgün source retrieval faizi və cavab keyfiyyətini əvvəl/sonra müqayisə et.\n6. Dəyişikliklərin trade-off və məhdudiyyətlərini yaz.\n\n## 4. Konkret nümunə və izah\nMətn hissəsi (chunk) sənədin kiçik parçasıdır; top-k axtarışdan götürülən hissələrin sayıdır. Əvvəl 300 söz/k=3, sonra 150 söz/k=3, sonda 150 söz/k=5 sına. 20 sualdan 15-də düzgün hissə tapılıbsa göstərici 15/20=75%-dir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, test dataset-i, retrieval ölçüləri, parametrlər üzrə müqayisə və nəticə hesabatı. Ölçüləri təkrar istehsal etmək mümkün olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər sınaqda yalnız bir parametr dəyişib; eyni sual dəsti istifadə olunub. Düzgün hissənin necə müəyyən olunduğu və əldə edilən faiz açıqdır.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Retrieve the top two relevant passages from three fictional FAQ documents and calculate precision@2.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / applied-ai-engineering / task-7` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Split fictional documents into passages with source IDs. Show evidence in a file, local demo or measurable test.\n4. Compare two chunk sizes on eight fixed questions using top-two results. Show evidence in a file, local demo or measurable test.\n5. Test that a missing source produces an unknown answer, not a fabricated claim. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Retrieve the top two relevant passages from three fictional FAQ documents and calculate precision@2. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nRetrieve the top two relevant passages from three fictional FAQ documents and calculate precision@2.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nImprove document retrieval quality and measure the effect of each change.\n\n## 2. Before you start\nYour document Q&A prototype, test questions, and source chunks. If embeddings/API access is unavailable, compare keyword-search alternatives.\n\n## 3. Step-by-step work\n1. Continue your own AI repository.\n2. Record the expected source chunk for at least 20 questions.\n3. Measure whether the correct chunk appears in the current top-k results.\n4. Experiment with chunk size and top-k one variable at a time.\n5. Compare source-retrieval rate and answer quality before/after.\n6. Document trade-offs and limitations.\n\n## 4. Concrete example and explanation\nA chunk is a short document passage; top-k is the number of retrieved passages. Compare 300 words/k=3, then 150 words/k=3, then 150 words/k=5. Finding the labelled passage for 15 of 20 questions gives 75%.\n\n## 5. What to submit\nYour own GitHub repository link, test dataset, retrieval metrics, parameter comparison, and report. Measurements must be reproducible.\n\n## 6. How to check your work\nChange one parameter per comparison and keep the same questions. State how relevant passages are labelled and how the percentage is calculated."},{"slug":"applied-ai-engineering","task_number":8,"title":"Guardrails","old_description":"[[AZ]]\nPrompt injection və həssas məlumat sızması risklərinə qarşı yoxlanıla bilən AI qoruyucuları qur.\n\n[[EN]]\nBuild testable AI safeguards against prompt injection and sensitive-data disclosure.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAI cavabları üçün təhlükəsizlik sərhədləri quracaq və riskli input-ların davranışını yoxlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz AI prototipin, input validation, prompt injection və privacy əsasları. Real şəxsi məlumat və zərərli əməliyyatlar işlətmə.\n\n## 3. Addım-addım icra\n1. Öz AI repo-nu davam etdir.\n2. İcazəli mövzuları, qadağan olunan əməliyyatları və cavab verilməyən halları yaz.\n3. Input uzunluğu, mənbə yoxlaması və tool icazələri üçün guardrail əlavə et.\n4. Prompt injection, şəxsi məlumat istəyi və əlaqəsiz suallar üçün sintetik testlər qur.\n5. Sistem uyğun olmayan input-u rədd etməli və ya təhlükəsiz cavab verməlidir.\n6. Hər guardrail üçün test və qalan risk qeydi əlavə et.\n\n## 4. Konkret nümunə və izah\nQoruyucu qayda (guardrail) konkret yoxlamadır: məsələn, giriş uzunluğunu məhdudlaşdırmaq, mənbəsiz cavabı dayandırmaq və naməlum alət çağırışını rədd etmək. Sadəcə prompta “təhlükəsiz ol” yazmaq yoxlanılan kod qaydasını əvəz etmir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, guardrail qaydaları, test cədvəli və test nəticələri. Guardrail-in bütün hücumları aradan qaldırdığını iddia etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər qayda üçün onu işə salan giriş, gözlənilən cavab və faktiki nəticə var. Normal sualların səhvən rədd olunması da yoxlanılıb.\n\n[[EN]]\n## 1. Goal\nSet safety boundaries for AI responses and test behavior on risky inputs.\n\n## 2. Before you start\nYour AI prototype, input validation, prompt-injection, and privacy basics. Do not use real personal data or harmful operations.\n\n## 3. Step-by-step work\n1. Continue your own AI repository.\n2. Define allowed topics, prohibited actions, and cases where the system should not answer.\n3. Add guardrails for input length, source checks, and tool permissions.\n4. Create synthetic tests for prompt injection, requests for personal data, and unrelated questions.\n5. The system should refuse or respond safely to disallowed inputs.\n6. Add tests and a residual-risk note for each guardrail.\n\n## 4. Concrete example and explanation\nA guardrail is a concrete check: limit input length, stop unsupported answers, or reject unknown tools. Merely asking the prompt to “be safe” does not replace an enforceable check.\n\n## 5. What to submit\nYour own GitHub repository link, guardrail rules, test table, and results. Do not claim guardrails eliminate every attack.\n\n## 6. How to check your work\nFor each rule show the triggering input, expected response, and actual result. Also check whether legitimate questions are wrongly rejected.","new_description":"[[AZ]]\nPrompt injection və həssas məlumat sızması risklərinə qarşı yoxlanıla bilən AI qoruyucuları qur.\n\nPulsuz alətlər: Python (free), Google Docs (personal), GitHub Free. Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nBuild testable AI safeguards against prompt injection and sensitive-data disclosure.\n\nFree tools: Python (free), Google Docs (personal), GitHub Free. See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Sənəddə 'Əvvəlki qaydanı unut' yazısı olsa da AI onu mənbə mətnindən gələn etibarsız məzmun kimi görməlidir.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / applied-ai-engineering / task-8` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Zərərsiz 5 sintetik risk ssenarisi yaz: prompt injection, şəxsi data tələb etmə, mənbəsiz cavab və s. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Giriş yoxlaması, mənbə limiti və təhlükəsiz fallback qaydalarını sənədləşdir. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Bütün ssenariləri yalnız lokal/fiktiv mühitdə test et, nəticəni öncə/sonra cədvəlində göstər. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Sənəddə 'Əvvəlki qaydanı unut' yazısı olsa da AI onu mənbə mətnindən gələn etibarsız məzmun kimi görməlidir. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nSənəddə 'Əvvəlki qaydanı unut' yazısı olsa da AI onu mənbə mətnindən gələn etibarsız məzmun kimi görməlidir.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAI cavabları üçün təhlükəsizlik sərhədləri quracaq və riskli input-ların davranışını yoxlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz AI prototipin, input validation, prompt injection və privacy əsasları. Real şəxsi məlumat və zərərli əməliyyatlar işlətmə.\n\n## 3. Addım-addım icra\n1. Öz AI repo-nu davam etdir.\n2. İcazəli mövzuları, qadağan olunan əməliyyatları və cavab verilməyən halları yaz.\n3. Input uzunluğu, mənbə yoxlaması və tool icazələri üçün guardrail əlavə et.\n4. Prompt injection, şəxsi məlumat istəyi və əlaqəsiz suallar üçün sintetik testlər qur.\n5. Sistem uyğun olmayan input-u rədd etməli və ya təhlükəsiz cavab verməlidir.\n6. Hər guardrail üçün test və qalan risk qeydi əlavə et.\n\n## 4. Konkret nümunə və izah\nQoruyucu qayda (guardrail) konkret yoxlamadır: məsələn, giriş uzunluğunu məhdudlaşdırmaq, mənbəsiz cavabı dayandırmaq və naməlum alət çağırışını rədd etmək. Sadəcə prompta “təhlükəsiz ol” yazmaq yoxlanılan kod qaydasını əvəz etmir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, guardrail qaydaları, test cədvəli və test nəticələri. Guardrail-in bütün hücumları aradan qaldırdığını iddia etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər qayda üçün onu işə salan giriş, gözlənilən cavab və faktiki nəticə var. Normal sualların səhvən rədd olunması da yoxlanılıb.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Treat a harmless 'ignore previous rule' sentence inside a local document as untrusted content.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / applied-ai-engineering / task-8` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Document five harmless synthetic risks, including prompt injection and unsupported claims. Show evidence in a file, local demo or measurable test.\n4. Define input checks, source boundaries and safe fallback behavior. Show evidence in a file, local demo or measurable test.\n5. Run only local fictional tests and compare before/after behavior. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Treat a harmless 'ignore previous rule' sentence inside a local document as untrusted content. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nTreat a harmless 'ignore previous rule' sentence inside a local document as untrusted content.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nSet safety boundaries for AI responses and test behavior on risky inputs.\n\n## 2. Before you start\nYour AI prototype, input validation, prompt-injection, and privacy basics. Do not use real personal data or harmful operations.\n\n## 3. Step-by-step work\n1. Continue your own AI repository.\n2. Define allowed topics, prohibited actions, and cases where the system should not answer.\n3. Add guardrails for input length, source checks, and tool permissions.\n4. Create synthetic tests for prompt injection, requests for personal data, and unrelated questions.\n5. The system should refuse or respond safely to disallowed inputs.\n6. Add tests and a residual-risk note for each guardrail.\n\n## 4. Concrete example and explanation\nA guardrail is a concrete check: limit input length, stop unsupported answers, or reject unknown tools. Merely asking the prompt to “be safe” does not replace an enforceable check.\n\n## 5. What to submit\nYour own GitHub repository link, guardrail rules, test table, and results. Do not claim guardrails eliminate every attack.\n\n## 6. How to check your work\nFor each rule show the triggering input, expected response, and actual result. Also check whether legitimate questions are wrongly rejected."},{"slug":"applied-ai-engineering","task_number":9,"title":"Cost and Latency","old_description":"[[AZ]]\nSüni sorğu izində token xərci və cavab gecikməsini ölç, sonra optimallaşdırmanı sın.\n\n[[EN]]\nMeasure token cost and response latency on a synthetic trace, then test an optimization.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAI prototipinin cavab vaxtını və təxmini istifadə xərclərini ölçərək səmərəli seçim edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz AI repo-n, test dataset-i və latency/token/cost anlayışları. API xərci yaratmaq istəmirsənsə, mock cavablarla vaxt ölç və qiymət hesabını nümunə kimi işarələ.\n\n## 3. Addım-addım icra\n1. Öz AI layihəni davam etdir.\n2. Eyni 20+ test sorğusunu bir neçə dəfə işə sal.\n3. Cavab vaxtını və istifadə olunan token/xərc məlumatını mövcuddursa qeyd et.\n4. Qısa context, retrieval top-k və model variantlarını təhlükəsiz testlə müqayisə et.\n5. Orta və p95 latency hesabla; mock/estimated qiymətləri real ölçü kimi təqdim etmə.\n6. Keyfiyyət, sürət və xərc arasında trade-off-u izah et.\n\n## 4. Konkret nümunə və izah\nGecikmə sorğu göndəriləndən cavab tamamlanana qədər keçən vaxtdır. p95 üçün vaxtları artan sırala və `ceil(0.95 × N)`-ci dəyəri götür. 20 ölçüdə bu, 19-cu dəyərdir. Xərc = giriş tokeni × giriş tarifi + çıxış tokeni × çıxış tarifi; tarifin vahidini nəzərə al.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, ölçmə skripti/cədvəli, latency nəticələri, xərc fərziyyələri və trade-off hesabatı. Hər nəticənin real, ölçülmüş və ya təxmin olduğu aydın göstərilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nSorğu sayı, təkrar sayı, ölçmə mühiti və vaxt vahidi yazılıb. Eyni cavab keyfiyyəti sınağı sürət dəyişikliyindən sonra da aparılıb; təxmini xərc ölçülmüş xərcdən ayrılıb.\n\n[[EN]]\n## 1. Goal\nMeasure response time and estimated usage cost to make a more efficient AI design choice.\n\n## 2. Before you start\nYour AI repository, test dataset, and latency/token/cost concepts. If you want to avoid API charges, measure mock responses and label price calculations as illustrative.\n\n## 3. Step-by-step work\n1. Continue your own AI project.\n2. Run the same 20+ test prompts multiple times.\n3. Record response time and token/cost data when available.\n4. Compare context length, retrieval top-k, and model variants using safe tests.\n5. Calculate average and p95 latency; do not present mock/estimated costs as real measurements.\n6. Explain quality, speed, and cost trade-offs.\n\n## 4. Concrete example and explanation\nLatency runs from request start to completed response. For p95, sort measurements and take item `ceil(0.95 × N)`; for 20 samples it is item 19. Cost = input tokens × input rate + output tokens × output rate, with matching rate units.\n\n## 5. What to submit\nYour own GitHub repository link, measurement script/table, latency results, cost assumptions, and trade-off report. Clearly label each result as measured, estimated, or simulated.\n\n## 6. How to check your work\nState sample count, repeats, environment, and time units. Rerun the quality evaluation after optimizing speed. Separate estimated cost from observed billing.","new_description":"[[AZ]]\nSüni sorğu izində token xərci və cavab gecikməsini ölç, sonra optimallaşdırmanı sın.\n\nPulsuz alətlər: Python (free), Google Sheets (personal). Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nMeasure token cost and response latency on a synthetic trace, then test an optimization.\n\nFree tools: Python (free), Google Sheets (personal). See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** 10 sintetik sorğu üçün `time.perf_counter()` ilə cavab gecikməsini ölç; token sayını yalnız təxmini hesabla, ödəniş etmə.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / applied-ai-engineering / task-9` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Kiçik lokal cavab funksiya/maketini 10 dəfə çağır və vaxtları millisanidə saxla. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Qısa və uzun prompt variantları üçün orta və p95 gecikməni müqayisə et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Qiymət rəsmi mənbədən yoxlanmayıbsa onu 'təxmini/simulyasiya' kimi işarələ. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: 10 sintetik sorğu üçün `time.perf_counter()` ilə cavab gecikməsini ölç; token sayını yalnız təxmini hesabla, ödəniş etmə. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\n10 sintetik sorğu üçün `time.perf_counter()` ilə cavab gecikməsini ölç; token sayını yalnız təxmini hesabla, ödəniş etmə.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAI prototipinin cavab vaxtını və təxmini istifadə xərclərini ölçərək səmərəli seçim edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz AI repo-n, test dataset-i və latency/token/cost anlayışları. API xərci yaratmaq istəmirsənsə, mock cavablarla vaxt ölç və qiymət hesabını nümunə kimi işarələ.\n\n## 3. Addım-addım icra\n1. Öz AI layihəni davam etdir.\n2. Eyni 20+ test sorğusunu bir neçə dəfə işə sal.\n3. Cavab vaxtını və istifadə olunan token/xərc məlumatını mövcuddursa qeyd et.\n4. Qısa context, retrieval top-k və model variantlarını təhlükəsiz testlə müqayisə et.\n5. Orta və p95 latency hesabla; mock/estimated qiymətləri real ölçü kimi təqdim etmə.\n6. Keyfiyyət, sürət və xərc arasında trade-off-u izah et.\n\n## 4. Konkret nümunə və izah\nGecikmə sorğu göndəriləndən cavab tamamlanana qədər keçən vaxtdır. p95 üçün vaxtları artan sırala və `ceil(0.95 × N)`-ci dəyəri götür. 20 ölçüdə bu, 19-cu dəyərdir. Xərc = giriş tokeni × giriş tarifi + çıxış tokeni × çıxış tarifi; tarifin vahidini nəzərə al.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, ölçmə skripti/cədvəli, latency nəticələri, xərc fərziyyələri və trade-off hesabatı. Hər nəticənin real, ölçülmüş və ya təxmin olduğu aydın göstərilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nSorğu sayı, təkrar sayı, ölçmə mühiti və vaxt vahidi yazılıb. Eyni cavab keyfiyyəti sınağı sürət dəyişikliyindən sonra da aparılıb; təxmini xərc ölçülmüş xərcdən ayrılıb.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Benchmark ten fictional queries with time.perf_counter and estimate tokens without paying for usage.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / applied-ai-engineering / task-9` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Measure ten runs of a local response function in milliseconds. Show evidence in a file, local demo or measurable test.\n4. Compare average and p95 latency for short and long inputs. Show evidence in a file, local demo or measurable test.\n5. Mark cost figures as illustrative unless based on verified official pricing. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Benchmark ten fictional queries with time.perf_counter and estimate tokens without paying for usage. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nBenchmark ten fictional queries with time.perf_counter and estimate tokens without paying for usage.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nMeasure response time and estimated usage cost to make a more efficient AI design choice.\n\n## 2. Before you start\nYour AI repository, test dataset, and latency/token/cost concepts. If you want to avoid API charges, measure mock responses and label price calculations as illustrative.\n\n## 3. Step-by-step work\n1. Continue your own AI project.\n2. Run the same 20+ test prompts multiple times.\n3. Record response time and token/cost data when available.\n4. Compare context length, retrieval top-k, and model variants using safe tests.\n5. Calculate average and p95 latency; do not present mock/estimated costs as real measurements.\n6. Explain quality, speed, and cost trade-offs.\n\n## 4. Concrete example and explanation\nLatency runs from request start to completed response. For p95, sort measurements and take item `ceil(0.95 × N)`; for 20 samples it is item 19. Cost = input tokens × input rate + output tokens × output rate, with matching rate units.\n\n## 5. What to submit\nYour own GitHub repository link, measurement script/table, latency results, cost assumptions, and trade-off report. Clearly label each result as measured, estimated, or simulated.\n\n## 6. How to check your work\nState sample count, repeats, environment, and time units. Rerun the quality evaluation after optimizing speed. Separate estimated cost from observed billing."},{"slug":"applied-ai-engineering","task_number":10,"title":"AI Product Handoff","old_description":"[[AZ]]\nAI prototipini başqa mühəndisin işə sala biləcəyi təhlükəsiz və ölçülə bilən handoff paketinə çevir.\n\n[[EN]]\nTurn an AI prototype into a safe, measurable handoff another engineer can run.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAI məhsulunu başqa developer-in davam etdirə bilməsi üçün kod, test və texniki qərarlarla birlikdə təhvil verəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 AI layihən, testlər, guardrails, retrieval ölçüləri və setup sənədləri.\n\n## 3. Addım-addım icra\n1. Öz əvvəlki AI repo-nu davam etdir.\n2. Quraşdırma, environment nümunəsi və local/mock run addımlarını yaz.\n3. Data flow, prompt, retrieval və tool icazələrini diaqramla izah et.\n4. Test nəticələri, məlum limitlər, privacy/safety riskləri və qiymət fərziyyələrini qeyd et.\n5. Mövcud test/lint/build əmrlərini işə sal və nəticələri əlavə et.\n6. Qısa demo və növbəti 3 prioritet işi təqdim et; secret-ləri çıxar.\n\n## 4. Konkret nümunə və izah\nLayihəni yeni qovluğa klonla, README-dəki əmrləri ardıcıllıqla icra et və sənədlərdəki nümunə sualı yoxla. Handoff başqa şəxsin layihəni səndən şifahi kömək almadan işə sala bilməsi üçün təhvil paketidir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, README, arxitektura diaqramı, test/benchmark nəticələri, demo və məlum məhdudiyyətlər. Fresh clone-dan quraşdırma təkrarlana bilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTəmiz quraşdırma, sənədlərə əsaslanan cavab və bütün sınaqlar təkrarlanır. Demo, məlum problemlər və üç növbəti prioritet eyni versiyaya aiddir.\n\n[[EN]]\n## 1. Goal\nHand off your AI product so another developer can continue it with the code, tests, and technical decisions documented.\n\n## 2. Before you start\nYour AI project from Tasks 1–9, tests, guardrails, retrieval metrics, and setup documentation.\n\n## 3. Step-by-step work\n1. Continue your own AI repository from earlier tasks.\n2. Document setup, environment examples, and local/mock run instructions.\n3. Diagram data flow, prompting, retrieval, and tool permissions.\n4. Record test results, known limits, privacy/safety risks, and cost assumptions.\n5. Run available test/lint/build commands and include the results.\n6. Provide a short demo and three next priorities; remove all secrets.\n\n## 4. Concrete example and explanation\nClone into a new folder, follow the README commands in order, and try the documented sample question. A handoff lets another person run and continue the project without verbal help.\n\n## 5. What to submit\nYour own GitHub repository link, README, architecture diagram, test/benchmark results, demo, and known limitations. Setup must be repeatable from a fresh clone.\n\n## 6. How to check your work\nVerify a clean installation, a sourced answer, and the test suite. The demo, known issues, and next three priorities must refer to the same version.","new_description":"[[AZ]]\nAI prototipini başqa mühəndisin işə sala biləcəyi təhlükəsiz və ölçülə bilən handoff paketinə çevir.\n\nPulsuz alətlər: GitHub Free, Google Docs (personal), Python (free). Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nTurn an AI prototype into a safe, measurable handoff another engineer can run.\n\nFree tools: GitHub Free, Google Docs (personal), Python (free). See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Yeni developer repo-nu klonlayıb `python -m ...` komandasını işlədə, nümunə sorğu verə və testləri başlada bilməlidir.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / applied-ai-engineering / task-10` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. README-yə quraşdırma, təhlükəsiz config və test addımlarını yaz. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Promptlar, sintetik məlumatlar, qiymətləndirmə cədvəli və məhdudiyyətləri repo-da ayrı saxla. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Başqasının ilk dəfə quraşdırdığı ssenarini addım-addım yoxla, sirləri GitHub-a göndərmə. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Yeni developer repo-nu klonlayıb `python -m ...` komandasını işlədə, nümunə sorğu verə və testləri başlada bilməlidir. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nYeni developer repo-nu klonlayıb `python -m ...` komandasını işlədə, nümunə sorğu verə və testləri başlada bilməlidir.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAI məhsulunu başqa developer-in davam etdirə bilməsi üçün kod, test və texniki qərarlarla birlikdə təhvil verəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 AI layihən, testlər, guardrails, retrieval ölçüləri və setup sənədləri.\n\n## 3. Addım-addım icra\n1. Öz əvvəlki AI repo-nu davam etdir.\n2. Quraşdırma, environment nümunəsi və local/mock run addımlarını yaz.\n3. Data flow, prompt, retrieval və tool icazələrini diaqramla izah et.\n4. Test nəticələri, məlum limitlər, privacy/safety riskləri və qiymət fərziyyələrini qeyd et.\n5. Mövcud test/lint/build əmrlərini işə sal və nəticələri əlavə et.\n6. Qısa demo və növbəti 3 prioritet işi təqdim et; secret-ləri çıxar.\n\n## 4. Konkret nümunə və izah\nLayihəni yeni qovluğa klonla, README-dəki əmrləri ardıcıllıqla icra et və sənədlərdəki nümunə sualı yoxla. Handoff başqa şəxsin layihəni səndən şifahi kömək almadan işə sala bilməsi üçün təhvil paketidir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, README, arxitektura diaqramı, test/benchmark nəticələri, demo və məlum məhdudiyyətlər. Fresh clone-dan quraşdırma təkrarlana bilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTəmiz quraşdırma, sənədlərə əsaslanan cavab və bütün sınaqlar təkrarlanır. Demo, məlum problemlər və üç növbəti prioritet eyni versiyaya aiddir.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** A new developer should clone the repository, run local commands, ask a sample question and execute tests.\n\n## Free tools and platforms\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / applied-ai-engineering / task-10` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Write setup, safe configuration and test commands in the README. Show evidence in a file, local demo or measurable test.\n4. Keep prompts, synthetic fixtures, evaluation results and limitations organized. Show evidence in a file, local demo or measurable test.\n5. Rehearse a clean installation and confirm no secrets are committed. Show evidence in a file, local demo or measurable test.\n6. Verify this example: A new developer should clone the repository, run local commands, ask a sample question and execute tests. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nA new developer should clone the repository, run local commands, ask a sample question and execute tests.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nHand off your AI product so another developer can continue it with the code, tests, and technical decisions documented.\n\n## 2. Before you start\nYour AI project from Tasks 1–9, tests, guardrails, retrieval metrics, and setup documentation.\n\n## 3. Step-by-step work\n1. Continue your own AI repository from earlier tasks.\n2. Document setup, environment examples, and local/mock run instructions.\n3. Diagram data flow, prompting, retrieval, and tool permissions.\n4. Record test results, known limits, privacy/safety risks, and cost assumptions.\n5. Run available test/lint/build commands and include the results.\n6. Provide a short demo and three next priorities; remove all secrets.\n\n## 4. Concrete example and explanation\nClone into a new folder, follow the README commands in order, and try the documented sample question. A handoff lets another person run and continue the project without verbal help.\n\n## 5. What to submit\nYour own GitHub repository link, README, architecture diagram, test/benchmark results, demo, and known limitations. Setup must be repeatable from a fresh clone.\n\n## 6. How to check your work\nVerify a clean installation, a sourced answer, and the test suite. The demo, known issues, and next three priorities must refer to the same version."}]$legacy_payload$::jsonb);
DO $preflight$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='applied-ai-engineering' AND t.title=e.item->>'title'
 AND t.instructions=e.item->>'old_instructions' AND t.description=e.item->>'old_description'
 AND t.status='published' AND t.is_required;
 IF (SELECT jsonb_array_length(payload) FROM legacy_guides)<>10 OR n<>10 THEN RAISE EXCEPTION 'Version mismatch in applied-ai-engineering: %',n; END IF;
END; $preflight$;
DO $apply$
DECLARE n integer;
BEGIN
 UPDATE public.internship_tasks t SET instructions=e.item->>'new_instructions',description=e.item->>'new_description'
 FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 WHERE i.slug='applied-ai-engineering' AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions' AND t.description=e.item->>'old_description';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>10 THEN RAISE EXCEPTION 'Expected 10 changed tasks for applied-ai-engineering, got %',n; END IF;
END; $apply$;
DO $verify$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='applied-ai-engineering' AND t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required;
 IF n<>10 THEN RAISE EXCEPTION 'Postcheck mismatch in applied-ai-engineering: %',n; END IF;
END; $verify$;
COMMIT;
